```tsx
import { useId } from "react";
import "./StreakBadge.css";

export interface StreakBadgeProps {
  /** Current day of the streak, counted from 1. */
  day: number;
  /** Length of the streak in days. */
  total: number;
}

export function StreakBadge({ day, total }: StreakBadgeProps) {
  const labelId = useId();

  const safeTotal = Number.isFinite(total) && total > 0 ? Math.floor(total) : 1;
  const safeDay = Number.isFinite(day)
    ? Math.min(Math.max(Math.floor(day), 0), safeTotal)
    : 0;
  const percent = (safeDay / safeTotal) * 100;

  return (
    <div
      className="streak-badge"
      role="group"
      aria-labelledby={labelId}
      tabIndex={0}
    >
      <span id={labelId} className="streak-badge__label">
        {`Day ${safeDay} of ${safeTotal}`}
      </span>
      <div
        className="streak-badge__track"
        role="progressbar"
        aria-label="Streak progress"
        aria-valuemin={0}
        aria-valuemax={safeTotal}
        aria-valuenow={safeDay}
        aria-valuetext={`Day ${safeDay} of ${safeTotal}`}
      >
        <span
          className="streak-badge__fill"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}
```

